catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {}

    if (newValue == "true") {
        if (g_user.hasRole("x_ndecd_triage_2_0.Orthophoniste")) {
            //cacher variables pour ecole
            //g_form.setVisible("est_ce_que_l_l_ve_fr_quente_pr_sentement_une_classe_distincte",false)
            //g_form.setMandatory("est_ce_que_l_l_ve_fr_quente_pr_sentement_une_classe_distincte",false)
            //g_form.setVisible("est_ce_que_l_l_ve_a_un_diagnostic",false)
            // g_form.setMandatory("est_ce_que_l_l_ve_a_un_diagnostic",false)
            // g_form.setVisible("situation_familiale_de_l_l_ve",false)
            // g_form.setMandatory("situation_familiale_de_l_l_ve",false)


            g_form.setVisible("orth_je_soumets_la_candidature_de_l_l_ve_au_x_programme_s", true)
            g_form.setMandatory("orth_je_soumets_la_candidature_de_l_l_ve_au_x_programme_s", true)
            g_form.setVisible("existe_t_il_un_rapport_d_valuation_en_orthophonie_au_dossier", false)
            g_form.setMandatory("existe_t_il_un_rapport_d_valuation_en_orthophonie_au_dossier", false)
        } else {
            // g_form.setVisible("est_ce_que_l_l_ve_fr_quente_pr_sentement_une_classe_distincte",true)
            // g_form.setMandatory("est_ce_que_l_l_ve_fr_quente_pr_sentement_une_classe_distincte",true)
            // g_form.setVisible("est_ce_que_l_l_ve_a_un_diagnostic",true)
            // g_form.setMandatory("est_ce_que_l_l_ve_a_un_diagnostic",true)
            // g_form.setVisible("situation_familiale_de_l_l_ve",true)
            // g_form.setMandatory("situation_familiale_de_l_l_ve",true)



            g_form.setVisible("existe_t_il_un_rapport_d_valuation_en_orthophonie_au_dossier", true)
            g_form.setMandatory("existe_t_il_un_rapport_d_valuation_en_orthophonie_au_dossier", true)
            g_form.setVisible("orth_je_soumets_la_candidature_de_l_l_ve_au_x_programme_s", false)
            g_form.setMandatory("orth_je_soumets_la_candidature_de_l_l_ve_au_x_programme_s", false)
        }
    } else {
        // g_form.setVisible("est_ce_que_l_l_ve_fr_quente_pr_sentement_une_classe_distincte",false)
        // g_form.setMandatory("est_ce_que_l_l_ve_fr_quente_pr_sentement_une_classe_distincte",false)
        // g_form.setVisible("est_ce_que_l_l_ve_a_un_diagnostic",false)
        // g_form.setMandatory("est_ce_que_l_l_ve_a_un_diagnostic",false)
        // g_form.setVisible("situation_familiale_de_l_l_ve",false)
        // g_form.setMandatory("situation_familiale_de_l_l_ve",false)

        g_form.setVisible("existe_t_il_un_rapport_d_valuation_en_orthophonie_au_dossier", false)
        g_form.setMandatory("existe_t_il_un_rapport_d_valuation_en_orthophonie_au_dossier", false)
        g_form.setVisible("orth_je_soumets_la_candidature_de_l_l_ve_au_x_programme_s", false)
        g_form.setMandatory("orth_je_soumets_la_candidature_de_l_l_ve_au_x_programme_s", false)
    }

    var student = g_form.getValue('l_ve');
    if (student) {
        var school;
        //Type appropriate comment here, and begin script below
        var now_GR = new GlideRecord('x_ndecd_triage_2_0_eleve');
        now_GR.addQuery('sys_id', student); // Priority is 4 – Low and,
        now_GR.query(response);
    }

    function response(result) {
        if (result.next()) {
            school = result.getValue('u_nom_de_l_cole');
            var admins = new GlideRecord('x_ndecd_triage_2_0_x_ndecd_school');
            admins.addQuery('sys_id', school); // Priority is 4 – Low and,
            admins.query(responseA);
        }
    }

    function responseA(result) {
        while (result.next()) {
            var u_admin = result.getValue('admins');
            g_form.setValue("direction", u_admin);
        }
    }
}
